-- mvtk/tiled/spawners/environment.lua
-- Generated by splitting mvtk.tiled.object_spawner handlers by domain.

local OP = require "mvtk.tiled.object_props"

return function(H)
    local handlers = {}

    local M = H.M
    local Util = H.Util
    local TriggerPayloads = H.TriggerPayloads
    local CollectibleManager = H.CollectibleManager
    local EnemyManager = H.EnemyManager
    local TileSnap = H.TileSnap
    local get_gate_manager = H.get_gate_manager
    local get_boss_arena = H.get_boss_arena
    local get_tile_settings = H.get_tile_settings
    local get_room_world_offset = H.get_room_world_offset
    local to_bool = H.to_bool
    local ambient_component_name = H.ambient_component_name
    local resolve_rect_size_pixels = H.resolve_rect_size_pixels
    local rect_scale_from_size = H.rect_scale_from_size
    local resolve_breakable_swap_extent = H.resolve_breakable_swap_extent
    local parse_color_string = H.parse_color_string
    local non_empty_string = H.non_empty_string
    local resolve_boss_preset = H.resolve_boss_preset
    local resolve_boss_display_name = H.resolve_boss_display_name
    local get_props = H.get_props
    local make_id = H.make_id
    local world_point = H.world_point
    local world_rect = H.world_rect
    local spawn_factory = H.spawn_factory
    local spawn_collection = H.spawn_collection
    local post_collectible_tiled_overrides = H.post_collectible_tiled_overrides
    local apply_scale = H.apply_scale
    local make_scale = H.make_scale
    local send_tiled_props = H.send_tiled_props
    local log_spawn = H.log_spawn
    local log_register = H.log_register
    local get_type_prop = H.get_type_prop
    local record_error = H.record_error
    local normalize_gate_type_name = H.normalize_gate_type_name
    local normalize_gate_item_name = H.normalize_gate_item_name
    local parse_drops_string = H.parse_drops_string
    local resolve_chest_loot_table = H.resolve_chest_loot_table
    local resolve_difficulty_scaling = H.resolve_difficulty_scaling
    local print = H.print
    local polyline_registry = H.polyline_registry

    local function optional_id(value)
        local id = non_empty_string(value)
        return id == "none" and nil or id
    end

function handlers.hazard(object, room_id)
    local props = get_props(object)

    local hazard_type = props.hazard_type or object.name or "spikes"
    local hazard_id = make_id(props, "hazard_id", "hazard", object, room_id)

    local world_x, world_y, pos = world_point(object, room_id)
    local scale_x, scale_y, width, height = rect_scale_from_size(object.width, object.height, 64, 32, 128, 64)

    print(string.format("[OBJECT_SPAWNER] DEBUG: hazard pos=(%.1f, %.1f) -> world=(%.1f, %.1f) size=(%.1fx%.1f) type=%s",
        object.x, object.y, world_x, world_y, width, height, hazard_type))

    local instance = spawn_factory("hazard_factory", pos, {
        hazard_id = hazard_id,
        hazard_type = hazard_type,
        damage = props.damage or 1,
        damage_interval = props.damage_interval or 0.5,
        stun_t = tonumber(props.stun_t) or -1,
        knockback_force = props.knockback_force or 300,
        required_resistance = optional_id(props.required_resistance) or "",
        instant_kill = to_bool(props.instant_kill, false),
        enabled = to_bool(props.enabled, true),
        sound_on_hit = props.sound_on_hit or "",
        retractable = props.retractable or false,
        retract_time = props.retract_time or 2.0,
        extend_time = props.extend_time or 2.0,
        start_retracted = props.start_retracted or false,
        arena_id = props.arena_id or "",
        active_phases = props.active_phases or "",
        pattern = props.pattern or "",
        pattern_speed = props.pattern_speed or 1.0,
        trigger_id = props.trigger_id or "",
        room_id = room_id,
    }, 1, "hazard")

    if not instance then
        return nil
    end

    log_spawn("hazard", hazard_id, world_x, world_y,
        string.format("(type: %s)", hazard_type))

    -- Scale collision to match Tiled object size
    if instance and props.active_phases and props.active_phases ~= "" then
        pcall(msg.post, instance, hash("set_active_phases"), { phases = props.active_phases })
    end

    if instance and (math.abs(scale_x - 1) > 0.001 or math.abs(scale_y - 1) > 0.001) then
        go.set_scale(vmath.vector3(scale_x, scale_y, 1), instance)
    end

    return instance
end

--- Handle chest object
-- DISABLED: Chests are now created by editor script during tilemap import
-- Tiled properties:
--   loot_table: string (loot table ID from developer/config/loot_tables.lua)
--   locked: bool (requires key to open)
--   key_required: string (key item ID)

function handlers.water_volume(object, room_id)
    local props = get_props(object)
    local water_id = string.format("water_%s_%d", tostring(room_id), object.id)
    local water_type = props.water_type or "water"

    local world_x, world_y, pos = world_point(object, room_id)
    local scale_x, scale_y, width, height = rect_scale_from_size(object.width, object.height, 64, 64, 128, 128)

    local water_drag = props.water_drag
    if water_drag == nil then
        water_drag = 0.85
    end

    local instance = spawn_factory("water_factory", pos, {
        water_id = water_id,
        water_type = water_type,
        width = width,
        height = height,
        swim_enabled = to_bool(props.swim_enabled, true),
        swim_speed_mult = props.swim_speed_mult or 0.7,
        water_drag = water_drag,
        damage = props.damage or 0,
        damage_interval = props.damage_interval or 1.0,
        current_direction = props.current_direction or "none",
        current_strength = props.current_strength or 0,
        buoyancy = props.buoyancy or 0.5,
        oxygen_drain = to_bool(props.oxygen_drain, true),
        oxygen_drain_rate = props.oxygen_drain_rate or 1.0,
        surface_y_offset = props.surface_y_offset or 0,
        splash_effect = to_bool(props.splash_effect, true),
        tint_color = props.tint_color or "",
        room_id = room_id,
    }, 1, "water volume")

    if not instance then
        return nil
    end

    local tint = parse_color_string(props.tint_color)
    if tint then
        pcall(msg.post, instance, hash("set_tint"), { color = tint })
    end

    if instance and (math.abs(scale_x - 1) > 0.001 or math.abs(scale_y - 1) > 0.001) then
        go.set_scale(vmath.vector3(scale_x, scale_y, 1), instance)
    end

    log_spawn("water volume", water_id, world_x, world_y)
    return instance
end

--- Handle crumble platform object
-- Tiled properties:
--   crumble_delay: number (seconds before falling)
--   respawn_time/respawn_delay: number (seconds to respawn, 0 = permanent)
--   shake_warn/shake_before_crumble: bool (visual warning before crumble)
--   one_way: bool (unused currently)

function handlers.camera_zone(object, room_id)
    local props = get_props(object)
    local zone_id = props.zone_id or string.format("camera_%s_%d", tostring(room_id), object.id)
    local _, _, pos = world_point(object, room_id)

    msg.post("main:/main_go#script", hash("register_camera_zone"), {
        id = zone_id,
        position = pos,
        width = object.width or 256,
        height = object.height or 256,
        room_id = room_id,
        camera_mode = props.camera_mode or "follow",
        zoom_level = props.zoom_level or 1.0,
        bounds_padding = props.bounds_padding or 0,
        parallax_override = props.parallax_override,
        lock_x = to_bool(props.lock_x, false),
        lock_y = to_bool(props.lock_y, false),
        focus_x = props.focus_x or 0,
        focus_y = props.focus_y or 0,
        smooth_follow = to_bool(props.smooth_follow, true),
        deadzone_width = props.deadzone_width or 0,
        deadzone_height = props.deadzone_height or 0,
        transition_speed = props.transition_speed or 5.0,
        auto_fit = to_bool(props.auto_fit, false),
        properties = props,
    })

    log_register("camera zone", zone_id, pos.x, pos.y)
    return zone_id
end

