--- Handle sign object
-- Tiled properties:
--   sign_id: string
--   text: string
--   title: string
--   display_mode: string ("toast", "dialogue", "tutorial")
--   dialogue_id: string
--   label: string
--   range: number
--   duration: number
--   trigger_once: bool
--   set_flag/requires_flag: string
--   sound_id: string

function handlers.music_trigger(object, room_id)
    local props = get_props(object)
    local trigger_id = make_id(props, "trigger_id", "music", object, room_id)
    local _, _, pos = world_rect(object, room_id, 128, 128)

    local instance = spawn_factory("music_trigger_factory", pos, {
        trigger_id = trigger_id,
        music_id = optional_id(props.music_id) or "",
        area_theme = optional_id(props.area_theme) or "",
        fade_time = props.fade_time or 0.5,
        stop_on_exit = to_bool(props.stop_on_exit, true),
        exit_music = optional_id(props.exit_music) or "",
        exit_area = optional_id(props.exit_area) or "",
        trigger_once = to_bool(props.trigger_once, false),
    }, 1, "music trigger")

    if not instance then return nil end

    send_tiled_props(instance, props)

    apply_scale(instance, object.width or 128, object.height or 128, 64, 64, 128, 128)

    log_spawn("music trigger", trigger_id, pos.x, pos.y)
    return instance
end

