--- Handle map marker object
-- Tiled properties:
--   marker_type: string ("poi", "objective", "custom", "save")
--   marker_icon: string (icon name)
--   marker_label: string (text label on map)
--   show_on_minimap: bool
--   show_on_world_map: bool
--   visible_from_start: bool (show before player discovers it)
--   discovery_radius: number (distance at which marker is discovered)
--   facing: int (direction the marker faces, for sprites)

function handlers.map_marker(object, room_id)
    local props = get_props(object)
    local marker_id = props.marker_id
    if marker_id == nil or tostring(marker_id) == "" then
        marker_id = string.format("map_marker_%s_%d", tostring(room_id), object.id)
    end

    -- Marker template is point-based. Ignore helper geometry objects if they
    -- were tagged with this type by mistake.
    if object.polyline or object.polygon then
        print(string.format("[OBJECT_SPAWNER] Skipping map_marker helper geometry '%s' (id=%s)",
            tostring(object.name), tostring(object.id)))
        return nil
    end

    local _, _, pos = world_point(object, room_id)

    msg.post("main:/main_go#script", hash("register_map_marker"), {
        id = marker_id,
        marker_type = props.marker_type or "poi",
        marker_icon = props.marker_icon or "marker_default",
        marker_label = props.marker_label or object.name or "",
        position = pos,
        room_id = room_id,
        show_on_minimap = to_bool(props.show_on_minimap, true),
        show_on_world_map = to_bool(props.show_on_world_map, true),
        visible_from_start = to_bool(props.visible_from_start, false),
        discovery_radius = props.discovery_radius or 100,
        facing = props.facing or 1,
        properties = props,
    })

    log_register("map marker", marker_id, pos.x, pos.y)
    return marker_id
end

--- Handle dialogue trigger object
-- Tiled properties:
--   dialogue_id: string (dialogue from narrative config)
--   trigger_once: bool
--   npc_id: string (optional NPC speaker)

function handlers.secret(object, room_id)
    local props = get_props(object)
    local secret_id = props.secret_id or string.format("secret_%s_%d", tostring(room_id), object.id)
    local secret_type = props.secret_type or "illusory_wall"
    local reveals_on = props.reveals_on or "touch"
    local _, _, pos = world_point(object, room_id)

    msg.post("main:/main_go#script", hash("register_secret"), {
        id = secret_id,
        secret_type = secret_type,
        reveals_on = reveals_on,
        required_ability = optional_id(props.required_ability) or "",
        hide_tiles = to_bool(props.hide_tiles, true),
        notification = to_bool(props.notification, true),
        notification_text = props.notification_text or "Secret Found!",
        reward_type = optional_id(props.reward_type) or "",
        reward_amount = tonumber(props.reward_amount) or 0,
        map_reveal = to_bool(props.map_reveal, true),
        position = pos,
        width = object.width or 64,
        height = object.height or 64,
        room_id = room_id,
        properties = props,
    })

    log_register("secret", secret_id .. " (type: " .. secret_type .. ", reveals_on: " .. reveals_on .. ")", pos.x, pos.y)
    return secret_id
end

--- Handle arena lock trigger (for boss fights)
-- Tiled properties:
--   arena_id: string (links to boss/arena)
--   lock_on_enter: bool

function handlers.spike_hazard(object, room_id)
    local props = get_props(object)
    -- Delegate to hazard handler with spike-specific defaults
    props.hazard_type = props.hazard_type or "spikes"
    props.damage = props.damage or 1
    props.knockback = props.knockback or 300
    props.knockback_direction = props.direction or "up"
    props.instant_kill = props.instant_kill or false
    object.properties = props
    return M.handlers.hazard(object, room_id)
end

--- Handle lava hazard (damage over time fire zone)
-- Tiled properties:
--   damage: number (damage per tick)
--   damage_interval: number (seconds between damage ticks)
--   knockback: number (knockback force)
--   immunity_ability: string (ability that grants immunity)

function handlers.lava_hazard(object, room_id)
    local props = get_props(object)
    props.hazard_type = props.hazard_type or "lava"
    props.damage = props.damage or 2
    props.damage_interval = props.damage_interval or 0.5
    props.knockback = props.knockback or 400
    props.knockback_direction = props.knockback_direction or "up"
    props.immunity_ability = props.immunity_ability or "lava_walk"
    object.properties = props
    return M.handlers.hazard(object, room_id)
end

--- Handle void hazard (instant death pit)
-- Tiled properties:
--   respawn_at_checkpoint: bool (if true, respawn at last checkpoint)
--   respawn_at_room_entrance: bool (if true, respawn at room entrance)

function handlers.void_hazard(object, room_id)
    local props = get_props(object)
    props.hazard_type = props.hazard_type or "void"
    props.damage = 999
    props.instant_kill = true
    props.knockback = 0
    object.properties = props
    return M.handlers.hazard(object, room_id)
end

-- ============================================================================
-- STATIC COLLISION (physics templates)
-- ============================================================================
-- Drop-in solid geometry authored as rectangles/shapes on an object layer via
-- the "Solid Box" / "Solid Slope" templates (tiled/templates/physics/). Each
-- spawns a STATIC collisionobject sized to the authored rectangle, in the
-- "solid" group the tilemap terrain already uses, so the player collides with
-- them identically to painted terrain -- but decoupled from the art tilesheet
-- (no need to reserve tile slots 2..20). Solid Box keeps a 128x128 prefab
-- collider (half-extents 64) as a runtime fallback for maps that have not been
-- regenerated. Solid Slope is authored as an editable polygon and baked into a
-- per-object convex hull at build time, so it has no runtime spawner here.

--- Solid box: full axis-aligned static collider sized to the drawn rectangle.
function handlers.collision_box(object, room_id)
    local _, _, pos, width, height = world_rect(object, room_id, 128, 128)
    local spawn_scale = make_scale(width, height, 64, 64, 128, 128)
    local instance = spawn_factory("collision_box_factory", pos, {}, spawn_scale, "solid box")
    if not instance then return nil end
    log_spawn("solid box", object.name or object.id, pos.x, pos.y,
        string.format("(size: %.0fx%.0f)", width, height))
    return instance
end

-- Aliases for convenience

-- Handler aliases for authored object type synonyms.
handlers.spikes = handlers.spike_hazard
handlers.lava = handlers.lava_hazard
handlers.pit = handlers.void_hazard
handlers.void = handlers.void_hazard

-- Static-collision synonyms resolved by object NAME. Tiled exports a
-- template-backed object with an empty type/class but keeps its name, so the
-- "Solid Box" template dispatches via its normalized name ("solid_box"). The
-- shorter synonyms also let a bare rectangle named "solid"/"ground"/"collision"
-- work without a template. Solid Slope has no runtime handler -- it is authored
-- as a polygon and baked into a per-object hull at build time.
handlers.solid_box = handlers.collision_box
handlers.solid = handlers.collision_box
handlers.ground = handlers.collision_box
handlers.collision = handlers.collision_box

    return handlers
end
